const body = $('Webhook').first().json.body || {};
const kb = $('Get KB').first().json || {};
const system = (kb.persona || '') +
  "\n\n=== معلومات المشروع (استخدمها كمصدر وحيد للحقائق) ===\n" + (kb.knowledge || '') +
  "\n\nتعليمات: رد بالعربي بنبرة محترمة وتسويقية تحل المشاكل. لو فيه صورة مرفقة (مثلاً سكرين شوت محادثة عميل على واتساب) اقراها واستخدم محتواها في ردك. لو معلومة مش موجودة فوق، قول إنك هتتأكد وترجع، وما تخترعش أسعار أو تفاصيل.";

const contents = [];
for (const h of (body.history || [])) {
  contents.push({ role: h.role === 'assistant' ? 'model' : 'user', parts: [{ text: String(h.content || '') }] });
}
if (contents.length === 0) contents.push({ role: 'user', parts: [{ text: String(body.message || '') }] });

if (body.image) {
  const data = String(body.image).replace(/^data:[^;]+;base64,/, '');
  contents[contents.length - 1].parts.push({ inline_data: { mime_type: body.image_mime || 'image/jpeg', data } });
}

return [{ json: { geminiBody: {
  system_instruction: { parts: [{ text: system }] },
  contents,
  generationConfig: { temperature: 0.6 }
} } }];
